"""The Pintas editor's own favicon: the rice-field emblem from
assets/pintas-logo.png, cropped to the round badge (no wordmark) and
downscaled. Stored as data: URIs so the editor stays a single page with
no extra files to serve, in the local editor, the exe and the playground.

The matching files are assets/favicon-16/32/48/64.png and assets/favicon.ico.
"""

ICON_32 = "data:image/png;base64,"
ICON_64 = "data:image/png;base64,"


def favicon_links():
    """<link> tags for the editor page's <head>."""
    return (
        '<link rel="icon" type="image/png" sizes="32x32" href="%s">\n'
        '<link rel="icon" type="image/png" sizes="64x64" href="%s">' % (ICON_32, ICON_64)
    )
